admin.src.zoomModal:
function openZoomScheduleModal(caseData, opts) {
    opts = opts || {};
    _zoomScheduleCase = caseData;
    if (_zoomScheduleCase) _zoomScheduleCase.origin_task_id = opts.originTaskId || null;
    var overlay = document.getElementById('zoomScheduleOverlay');
    var gpBlock = document.getElementById('zoomGpBlock');
    var stageSelect = document.getElementById('zoomStageSelect');
    var notesField = document.getElementById('zoomAdminNotes');
    var initials = ((caseData.first_name || '')[0] || '') + ((caseData.last_name || '')[0] || '');
    gpBlock.innerHTML = '<div class="case-avatar" style="width:36px;height:36px;font-size:12px">' + esc(initials.toUpperCase()) + '</div>'
      + '<div><div style="font-size:13px;font-weight:700">' + esc(caseData.first_name || '') + ' ' + esc(caseData.last_name || '') + '</div>'
      + '<div style="font-size:11px;color:var(--muted)">' + esc(caseData.email || '') + (caseData.phone ? ' \u00b7 ' + esc(caseData.phone) : '') + '</div></div>';
    stageSelect.value = caseData.stage || 'myintealth';
    notesField.value = '';
    var reasonField = document.getElementById('zoomMeetingReason');
    if (reasonField) reasonField.value = '';
    if (opts.originTaskId && opts.autoSuggestReason) { autofillZoomReason(opts.originTaskId); }
    document.getElementById('zoomNotifyWhatsapp').checked = true;
    document.getElementById('zoomNotifyEmail').checked = true;
    document.getElementById('zoomScheduleBtn').disabled = false;
    document.getElementById('zoomScheduleBtn').textContent = 'Send Zoom Invite';
    overlay.classList.add('open');
  }
